/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountPadlockToggle, type PadlockToggleOptions } from "../../components/padlock-toggle/PadlockToggleEngine.js";
import type { MotionController } from "../../components/padlock-toggle/motion-runtime";

export function PadlockToggle({ options, className }: { options?: PadlockToggleOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountPadlockToggle(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="padlock-toggle" />;
}

